#include "pvdg_ui_snapshot.h"
#include <math.h>
#include <stdio.h>

static void set_measurement(pvdg_ui_measurement_t *m,int available,double value){if(!m)return;m->available=available!=0&&isfinite(value);m->value=m->available?value:0.0;m->quality=m->available?PVDG_UI_QUALITY_GOOD:PVDG_UI_QUALITY_UNAVAILABLE;}
size_t pvdg_ui_snapshot_export_core(char *buffer,size_t size,const pvdg_ui_model_t *m){if(!buffer||size==0U||!m)return 0U;int n=snprintf(buffer,size,"PVDG1;%d;%d;%d;%d;%d;%d;%d;%.6f;%d;%.6f;%d;%d;%d;%d;%d;%.6f;%d;%.6f;%d;%d;%lu",m->valid?1:0,m->network.online?1:0,m->network.rssi,m->grid.power_kw.available?1:0,m->grid.available?1:0,m->grid.breaker_known?1:0,m->grid.breaker_closed?1:0,m->grid.power_kw.value,m->solar.measured_kw.available?1:0,m->solar.measured_kw.value,m->generator.running?1:0,m->generator.breaker_known?1:0,m->generator.breaker_closed?1:0,m->generator.evidence_configured?1:0,m->generator.measured_kw.available?1:0,m->generator.measured_kw.value,m->load.power_kw.available?1:0,m->load.power_kw.value,m->load.derived?1:0,(int)m->export_policy.kind,(unsigned long)m->alarm_flags);if(n<0||(size_t)n>=size){buffer[0]='\0';return 0U;}return(size_t)n;}
bool pvdg_ui_snapshot_import_core(const char *text,pvdg_ui_model_t *m){if(!text||!m)return false;int valid=0,network=0,rssi=0,grid_m=0,grid_available=0,grid_known=0,grid_closed=0,solar_m=0,gen_running=0,gen_known=0,gen_closed=0,gen_evidence=0,gen_m=0,load_m=0,load_derived=0,policy=0,consumed=0;double grid=0.0,solar=0.0,gen=0.0,load=0.0;unsigned long alarms=0UL;int matched=sscanf(text,"PVDG1;%d;%d;%d;%d;%d;%d;%d;%lf;%d;%lf;%d;%d;%d;%d;%d;%lf;%d;%lf;%d;%d;%lu%n",&valid,&network,&rssi,&grid_m,&grid_available,&grid_known,&grid_closed,&grid,&solar_m,&solar,&gen_running,&gen_known,&gen_closed,&gen_evidence,&gen_m,&gen,&load_m,&load,&load_derived,&policy,&alarms,&consumed);if(matched!=21)return false;while(text[consumed]=='\n'||text[consumed]=='\r')consumed++;if(text[consumed]!='\0')return false;if(policy<PVDG_UI_EXPORT_POLICY_UNKNOWN||policy>PVDG_UI_EXPORT_POLICY_MINIMUM_IMPORT)return false;pvdg_ui_model_reset(m);m->valid=valid!=0;m->network.online=network!=0;m->network.rssi=rssi;set_measurement(&m->grid.power_kw,grid_m,grid);m->grid.available=grid_available!=0;m->grid.breaker_known=grid_known!=0;m->grid.breaker_closed=grid_closed!=0;set_measurement(&m->solar.measured_kw,solar_m,solar);m->generator.running=gen_running!=0;m->generator.breaker_known=gen_known!=0;m->generator.breaker_closed=gen_closed!=0;m->generator.evidence_configured=gen_evidence!=0;set_measurement(&m->generator.measured_kw,gen_m,gen);set_measurement(&m->load.power_kw,load_m,load);m->load.derived=load_derived!=0;m->export_policy.kind=(pvdg_ui_export_policy_kind_t)policy;m->alarm_flags=(uint32_t)alarms;return true;}
